def _as_cutoff(value: Any) -> float | None:
    """Coerce a ``cutoff``-like value to a finite float, or ``None``."""
    if isinstance(value, bool) or value is None:
        return None
    try:
        cutoff = float(value)
    except (TypeError, ValueError):
        return None
    return cutoff if math.isfinite(cutoff) else None


